import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { X, Check } from 'lucide-react';

const ValuationModal = ({ isOpen, onClose }) => {
  const [currentStep, setCurrentStep] = useState(1);
  const [formData, setFormData] = useState({
    brand: '',
    model: '',
    year: '',
    version: '',
    odo: '',
    sellTime: ''
  });

  const navigate = useNavigate();

  if (!isOpen) return null;

  const carModels = {
    Toyota: [
      'Camry', 'Corolla', 'Corolla Altis', 'Corolla Hatchback', 'Yaris', 'Crown', 'Prius', 'Mirai', 'Aygo', 'Aygo X',
      'Raize', 'Corolla Cross', 'C-HR', 'RAV4', 'Venza', 'Harrier', 'Highlander', 'Grand Highlander', 'Fortuner', 'Land Cruiser', 'Land Cruiser Prado', 'Sequoia',
      'Avanza', 'Veloz', 'Innova', 'Innova Hycross', 'Sienta', 'Noah', 'Voxy', 'Alphard', 'Vellfire', 'Sienna',
      'Hilux', 'Tacoma', 'Tundra',
      'GR Supra', 'GR86', 'GR Corolla', 'GR Yaris'
    ],
    Honda: ['City', 'Civic', 'Accord', 'Brio', 'CR-V', 'HR-V', 'BR-V', 'Mobilio'],
    Mazda: ['Mazda2', 'Mazda3', 'Mazda6', 'CX-3', 'CX-30', 'CX-5', 'CX-8', 'Mazda5'],
    Ford: ['Fiesta', 'Focus', 'EcoSport', 'Territory', 'Everest', 'Explorer', 'Tourneo', 'Ranger', 'Ranger Raptor'],
    Hyundai: ['i10', 'Accent', 'Elantra', 'Creta', 'Tucson', 'Santa Fe', 'Stargazer', 'Palisade', 'Custin'],
    Kia: ['Morning', 'Soluto', 'K3', 'K5', 'Sonet', 'Seltos', 'Carens', 'Sportage', 'Sorento', 'Carnival'],
    'Mercedes-Benz': ['A-Class', 'C-Class', 'E-Class', 'S-Class', 'GLA', 'GLB', 'GLC', 'GLE', 'GLS', 'G-Class', 'C43 AMG', 'C63 AMG', 'GLC43 AMG', 'G63 AMG', 'E53 AMG'],
    BMW: ['3 Series', '5 Series', '7 Series', 'X1', 'X3', 'X4', 'X5', 'X6', 'X7', '4 Series', '8 Series', 'M3', 'M4', 'M5', 'M8', 'X3 M', 'X5 M'],
    Mitsubishi: ['Attrage', 'Mirage', 'Xforce', 'Outlander', 'Pajero Sport', 'Xpander', 'Xpander Cross', 'Triton'],
    Nissan: ['Sunny', 'Almera', 'Kicks', 'X-Trail', 'Terra', 'Livina', 'Navara']
  };

  const handleNext = () => {
    if (currentStep < 6) setCurrentStep(currentStep + 1);
    else {
      // Navigate to the result page with the form data
      onClose(); // Prevent modal staying open in background
      navigate('/valuation-result', { state: { formData } });
    }
  };

  const steps = [
    { id: 1, key: 'brand', title: 'Hãng xe', type: 'select', placeholder: 'Chọn hãng xe', options: ['Toyota', 'Honda', 'Hyundai', 'Kia', 'Mazda', 'Mercedes-Benz', 'BMW', 'Ford', 'Mitsubishi', 'Nissan', 'Suzuki', 'VinFast', 'Chevrolet', 'MG', 'Peugeot'] },
    { id: 2, key: 'model', title: 'Dòng xe', type: 'select', placeholder: 'Chọn dòng xe', options: formData.brand && carModels[formData.brand] ? carModels[formData.brand] : [] },
    { id: 3, key: 'year', title: 'Đời xe', type: 'select', placeholder: 'Chọn đời xe', options: ['2024', '2023', '2022', '2021', '2020', '2019', '2018', '2017', '2016', '2015'] },
    { id: 4, key: 'version', title: 'Phiên bản', type: 'select', placeholder: 'Chọn phiên bản', options: ['Tiêu chuẩn', 'Cao cấp', 'Phiên bản khác'] },
    { id: 5, key: 'odo', title: 'Công tơ mét', type: 'input', placeholder: 'Nhập số Km đã đi' },
    { id: 6, key: 'sellTime', title: 'Khi nào bạn muốn bắt đầu bán xe?', type: 'select', placeholder: 'Chọn thời gian', options: ['Ngay bây giờ', 'Trong 1 tuần', 'Trong 1 tháng'] }
  ];

  const handleInputChange = (key, value) => {
    if (key === 'brand') {
      setFormData(prev => ({ ...prev, brand: value, model: '' }));
    } else {
      setFormData(prev => ({ ...prev, [key]: value }));
    }
  };

  const isStepCompleted = (stepId) => currentStep > stepId || formData[steps.find(s => s.id === stepId).key] !== '';

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-2xl w-full max-w-[650px] flex flex-col shadow-2xl relative">

        {/* Close Button */}
        <button 
          onClick={onClose}
          className="absolute top-4 right-4 text-gray-400 hover:text-gray-600 transition"
        >
          <X size={24} />
        </button>

        <div className="p-10 pl-16">
          <div className="relative">
            {/* Vertical Line Connecting Steps */}
            <div className="absolute left-4 top-4 bottom-12 w-px bg-gray-200 z-0"></div>

            {steps.map((step, index) => {
              const isActive = currentStep === step.id;
              const isPast = currentStep > step.id;
              const isFuture = currentStep < step.id;

              return (
                <div key={step.id} className="relative z-10 flex min-h-[70px] mb-2">

                  {/* Step Indicator */}
                  <div className="flex-shrink-0 flex justify-center w-8 mr-6 mt-1">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold transition-all duration-300 ${isActive ? 'bg-[#00d68f] text-white shadow-md shadow-green-200' : isPast ? 'bg-[#00d68f] text-white' : 'bg-gray-200 text-white'}`}>
                      {isPast ? <Check size={16} strokeWidth={3} /> : step.id}
                    </div>
                  </div>

                  {/* Step Content */}
                  <div className="flex-1 flex flex-col md:flex-row md:items-start pt-2 gap-2">
                    <div className="w-full md:w-36 text-sm text-gray-600 mt-1.5 flex-shrink-0">
                      {step.title}
                    </div>

                    <div className="flex-1 w-full max-w-[300px]">
                      {(isActive || formData[step.key]) ? (
                        <>
                          {step.type === 'select' ? (
                            <select 
                              value={formData[step.key]}
                              onChange={(e) => handleInputChange(step.key, e.target.value)}
                              className={`w-full border-2 rounded-xl px-4 py-2.5 text-sm appearance-none outline-none transition-all cursor-pointer bg-white ${isActive ? 'border-[#0096ff] text-[#0096ff] font-semibold' : 'border-gray-200 text-gray-800 font-medium'}`}
                              disabled={isFuture}
                            >
                              <option value="" disabled>{step.placeholder}</option>
                              {step.options.map((opt, i) => <option key={i} value={opt} className="text-gray-800">{opt}</option>)}
                            </select>
                          ) : (
                            <input
                              type="number"
                              value={formData[step.key]}
                              onChange={(e) => handleInputChange(step.key, e.target.value)}
                              placeholder={step.placeholder}
                              className={`w-full border-2 rounded-xl px-4 py-2.5 text-sm outline-none transition-all bg-white ${isActive ? 'border-[#0096ff] text-[#0096ff] font-semibold' : 'border-gray-200 text-gray-800 font-medium'}`}
                              disabled={isFuture}
                            />
                          )}
                        </>
                      ) : null}
                    </div>
                  </div>

                </div>
              );
            })}
          </div>

          <div className="flex justify-end mt-4">
            <button 
              onClick={handleNext}
              disabled={!formData[steps[currentStep - 1].key]}
              className="bg-[#0096ff] text-white px-8 py-2.5 rounded-xl text-sm font-bold shadow-md hover:bg-blue-600 hover:shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {currentStep === 6 ? 'Nhận báo giá' : 'Tiếp theo'}
            </button>
          </div>
        </div>

      </div>
    </div>
  );
};

export default ValuationModal;
